import {project} from './xinyi-street-world.js';
export function stationPoint(s,x,z){const c=Math.cos(s.heading),n=Math.sin(s.heading);return [(s.visualX??s.x)+c*x+n*z,(s.visualZ??s.z)-n*x+c*z];}
export function candidateSlots(s){if(s.slots)return s.slots;const rows=Math.ceil(s.dockCount/Math.max(1,s.columns));return Array.from({length:s.dockCount},(_,i)=>{const row=Math.floor(i/s.columns),columns=Math.min(s.columns,s.dockCount-row*s.columns);return {x:(i%s.columns-(columns-1)/2)*.75,z:(row-(rows-1)/2)*2.3,occupied:Math.floor((i+1)*s.bikeCount/s.dockCount)>Math.floor(i*s.bikeCount/s.dockCount)};});}
const inside=(p,r)=>{let v=false;for(let i=0,j=r.length-1;i<r.length;j=i++){const a=r[i],b=r[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])v=!v;}return v;};
const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
// Road rings can be concave: vertex inclusion plus edge intersection, including touching.
function intersects(a,b){if(a.some(p=>inside(p,b))||b.some(p=>inside(p,a)))return true;for(let i=0;i<a.length;i++)for(let j=0;j<b.length;j++){const p=a[i],q=a[(i+1)%a.length],r=b[j],s=b[(j+1)%b.length];if(Math.max(p[0],q[0])<Math.min(r[0],s[0])||Math.max(r[0],s[0])<Math.min(p[0],q[0])||Math.max(p[1],q[1])<Math.min(r[1],s[1])||Math.max(r[1],s[1])<Math.min(p[1],q[1]))continue;if(cross(p,q,r)*cross(p,q,s)<=0&&cross(r,s,p)*cross(r,s,q)<=0)return true;}return false;}
export function createRoadGuard(features=[],laneData=null){const rings=[],grid=new Map(),cell=32;function add(p,id){if(p.length<3)return;const xs=p.map(v=>v[0]),zs=p.map(v=>v[1]),box=[Math.min(...xs),Math.min(...zs),Math.max(...xs),Math.max(...zs)],i=rings.length;rings.push({p,id,box});for(let x=Math.floor(box[0]/cell);x<=Math.floor(box[2]/cell);x++)for(let z=Math.floor(box[1]/cell);z<=Math.floor(box[3]/cell);z++){const k=x+','+z;if(!grid.has(k))grid.set(k,[]);grid.get(k).push(i);}}
for(const f of features){if(f.kind!=='road'||f.tags?.tunnel==='yes'||Number(f.tags?.layer)<0||Number(f.tags?.layer)>0)continue;for(const path of f.paths??[])for(let i=1;i<path.length;i++){const a=project(...path[i-1]),b=project(...path[i]),dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz);if(!len)continue;const w=(f.width||6)/2,nx=-dz/len*w,nz=dx/len*w;add([[a[0]+nx,a[1]+nz],[b[0]+nx,b[1]+nz],[b[0]-nx,b[1]-nz],[a[0]-nx,a[1]-nz]],'road:'+f.id);}}
for(const type of ['Driving','Bus','Shoulder','Construction','Biking','intersection'])for(const r of type==='intersection'?laneData?.intersections??[]:laneData?.lanes?.[type]??[]){const p=[];for(let i=0;i<r.length;i+=2)p.push([r[i],r[i+1]]);add(p,'lane:'+type);}
return {count:rings.length,overlap(p){const xs=p.map(v=>v[0]),zs=p.map(v=>v[1]),box=[Math.min(...xs),Math.min(...zs),Math.max(...xs),Math.max(...zs)],seen=new Set();for(let x=Math.floor(box[0]/cell);x<=Math.floor(box[2]/cell);x++)for(let z=Math.floor(box[1]/cell);z<=Math.floor(box[3]/cell);z++)for(const i of grid.get(x+','+z)??[]){if(seen.has(i))continue;seen.add(i);const r=rings[i];if(box[0]>r.box[2]||box[2]<r.box[0]||box[1]>r.box[3]||box[3]<r.box[1])continue;if(intersects(p,r.p))return r.id;}return null;}};}
export function auditStationLayout(s,guard){const slots=candidateSlots(s),conflicts=[];for(let i=0;i<slots.length;i++){const p=slots[i];for(const [kind,x0,z0,x1,z1] of [['dock',-.22,-.28,.22,.28],['bike',-.4,-1.72,.4,.42]]){const box=[[x0,z0],[x1,z0],[x1,z1],[x0,z1]].map(([x,z])=>stationPoint(s,p.x+x,p.z+z));const road=guard.overlap(box);if(road)conflicts.push({slot:i,kind,road});}}if(s.slots?.length){const p=s.slots[0],box=[[-1.05,-.15],[-.35,-.15],[-.35,.15],[-1.05,.15]].map(([x,z])=>stationPoint(s,p.x+x,p.z+z));const road=guard.overlap(box);if(road)conflicts.push({slot:0,kind:'beacon',road});}return {candidateDocks:slots.length,conflicts,clear:conflicts.length===0};}
